numbers = [1, 2, 3, 4, 5]
keys = ["name", "domain", "symbol"]
values = ["Zeus", "Sky", "Thunderbolt"]
original_dict = {"a": 1, "b": 2, "c": 3}
data_tuples = [("Athena", 95), ("Ares", 70), ("Apollo", 85), ("Hermes", 60)]
god_powers = {"Zeus": 100, "Poseidon": 90, "Hades": 80, "Dionysus": 65}

# Task 1: Numbers to squares
squares_dict = {num: num**2 for num in numbers}

# Task 2: Parallel lists to dictionary
god_dict = {keys[i]: values[i] for i in range(len(keys))}

# Task 3: Transform dictionary (uppercase keys, double values)
transformed_dict = {k.upper(): v * 2 for k, v in original_dict.items()}

# Task 4: Create dictionary from list of tuples
power_dict = {god: power for god, power in data_tuples}

# Task 5: Filter dictionary (power > 80)
high_power_dict = {god: power for god, power in god_powers.items() if power > 80}

